#!/usr/bin/env python3
import csv
import json
import os
import sys
from pyscipopt import Model, quicksum

def read_csv(path):
    with open(path, 'r') as f:
        return list(csv.DictReader(f))

def main():
    data_dir = '/app/data'
    out_dir = '/app/submissions'
    os.makedirs(out_dir, exist_ok=True)

    # Read all data
    months = read_csv(f'{data_dir}/months.csv')
    products = read_csv(f'{data_dir}/products.csv')
    materials = read_csv(f'{data_dir}/materials.csv')
    bom = read_csv(f'{data_dir}/material_bom.csv')
    plants = read_csv(f'{data_dir}/plants.csv')
    pp_costs = read_csv(f'{data_dir}/plant_product_costs.csv')
    pp_rules = read_csv(f'{data_dir}/plant_product_rules.csv')
    mat_supply = read_csv(f'{data_dir}/material_supply.csv')
    mat_contracts = read_csv(f'{data_dir}/material_contracts.csv')
    dcs = read_csv(f'{data_dir}/distribution_centers.csv')
    customers = read_csv(f'{data_dir}/customers.csv')
    demand = read_csv(f'{data_dir}/demand.csv')
    avail = read_csv(f'{data_dir}/plant_month_availability.csv')
    p2d = read_csv(f'{data_dir}/plant_to_dc_routes.csv')
    d2c = read_csv(f'{data_dir}/dc_to_customer_routes.csv')
    safety = read_csv(f'{data_dir}/safety_stock.csv')
    inv_caps = read_csv(f'{data_dir}/inventory_caps.csv')
    service = read_csv(f'{data_dir}/customer_service_requirements.csv')
    co2_budget = read_csv(f'{data_dir}/monthly_co2_budget.csv')
    exceptions = read_csv(f'{data_dir}/route_product_exceptions.csv')
    share_rules = read_csv(f'{data_dir}/customer_product_share_rules.csv')
    split_rules = read_csv(f'{data_dir}/split_delivery_rules.csv')
    transport_modes = read_csv(f'{data_dir}/transport_modes.csv')
    mode_cap = read_csv(f'{data_dir}/monthly_mode_capacity.csv')
    tiers = read_csv(f'{data_dir}/material_contract_tiers.csv')

    # Build lookup structures
    month_list = [m['month'] for m in months]
    month_idx = {m['month']: int(m['period_index']) for m in months}
    prod_list = [p['product_id'] for p in products]
    mat_list = [m['material_id'] for m in materials]
    plant_list = [p['plant_id'] for p in plants]
    dc_list = [d['dc_id'] for d in dcs]
    cust_list = [c['customer_id'] for c in customers]

    # Plant data
    plant_data = {}
    for p in plants:
        plant_data[p['plant_id']] = {
            'reg_cap': float(p['regular_capacity_tons']),
            'ot_cap': float(p['overtime_capacity_tons']),
            'min_run': float(p['min_run_tons']),
            'fixed_cost': float(p['fixed_operating_cost']),
            'startup_cost': float(p['startup_cost']),
            'initial_open': int(p['initial_open']),
            'min_uptime': int(p['min_uptime_months'])
        }

    # Plant-product costs
    pp_cost = {}
    for r in pp_costs:
        pp_cost[(r['plant_id'], r['product_id'])] = {
            'reg_cost': float(r['regular_conversion_cost_per_ton']),
            'ot_cost': float(r['overtime_premium_cost_per_ton']),
            'reg_cons': float(r['regular_capacity_consumption_per_ton']),
            'ot_cons': float(r['overtime_capacity_consumption_per_ton']),
            'co2': float(r['process_co2_kg_per_ton'])
        }

    # Plant-product rules
    pp_rule = {}
    for r in pp_rules:
        pp_rule[(r['plant_id'], r['product_id'])] = {
            'qual_month': r['qualified_from_month'],
            'min_batch': float(r['min_batch_tons_if_produced']),
            'max_out': float(r['max_monthly_output_tons']),
            'setup_cost': float(r['setup_cost_per_month'])
        }

    # Material supply
    mat_sup = {}
    for r in mat_supply:
        mat_sup[(r['month'], r['plant_id'], r['material_id'])] = {
            'max': float(r['max_purchase_tons']),
            'cost': float(r['purchase_cost_per_ton']),
            'co2': float(r['material_co2_kg_per_ton'])
        }

    # Material contracts
    mat_con = {}
    for r in mat_contracts:
        mat_con[(r['month'], r['plant_id'], r['material_id'])] = float(r['min_purchase_tons_if_open'])

    # BOM
    bom_data = {}
    for r in bom:
        bom_data[(r['product_id'], r['material_id'])] = float(r['tons_material_per_ton_product'])

    # DC data
    dc_data = {}
    for d in dcs:
        dc_data[d['dc_id']] = {
            'storage': float(d['storage_capacity_tons']),
            'holding': float(d['holding_cost_per_ton_month']),
            'inbound': float(d['inbound_throughput_tons']),
            'outbound': float(d['outbound_throughput_tons'])
        }

    # Customer data
    cust_data = {}
    for c in customers:
        cust_data[c['customer_id']] = float(c['shortage_penalty_per_ton'])

    # Product multipliers
    prod_mult = {}
    for p in products:
        prod_mult[p['product_id']] = {
            'hold': float(p['inventory_holding_multiplier']),
            'short': float(p['shortage_penalty_multiplier'])
        }

    # Availability
    avail_data = {}
    for r in avail:
        avail_data[(r['month'], r['plant_id'])] = {
            'reg': float(r['regular_capacity_factor']),
            'ot': float(r['overtime_capacity_factor'])
        }

    # Plant to DC routes
    p2d_data = {}
    for r in p2d:
        p2d_data[(r['plant_id'], r['dc_id'])] = {
            'cost': float(r['transport_cost_per_ton']),
            'cap': float(r['monthly_capacity_tons']),
            'co2': float(r['transport_co2_kg_per_ton']),
            'fixed': float(r['fixed_cost_per_month']),
            'min': float(r['min_shipment_tons_if_used'])
        }

    # DC to customer routes
    d2c_data = {}
    for r in d2c:
        d2c_data[(r['dc_id'], r['customer_id'])] = {
            'cost': float(r['transport_cost_per_ton']),
            'cap': float(r['monthly_capacity_tons']),
            'co2': float(r['transport_co2_kg_per_ton']),
            'fixed': float(r['fixed_cost_per_month']),
            'min': float(r['min_shipment_tons_if_used'])
        }

    # Safety stock
    safety_data = {}
    for r in safety:
        safety_data[(r['month'], r['dc_id'], r['product_id'])] = float(r['min_inventory_tons'])

    # Inventory caps
    inv_cap_data = {}
    for r in inv_caps:
        inv_cap_data[(r['month'], r['dc_id'], r['product_id'])] = float(r['max_inventory_tons'])

    # Service requirements
    service_data = {}
    for r in service:
        service_data[(r['customer_id'], r['product_id'])] = {
            'fill': float(r['min_horizon_fill_rate']),
            'max_short': float(r['max_monthly_shortage_fraction'])
        }

    # CO2 budget
    co2_bud = {r['month']: float(r['co2_budget_kg']) for r in co2_budget}

    # Route product exceptions
    excl1 = set()  # plant_dc
    excl2 = set()  # dc_customer
    for r in exceptions:
        if r['route_type'] == 'plant_dc' and r['allowed'] == '0':
            excl1.add((r['from_id'], r['to_id'], r['product_id']))
        elif r['route_type'] == 'dc_customer' and r['allowed'] == '0':
            excl2.add((r['from_id'], r['to_id'], r['product_id']))

    # Share rules
    share_data = {}
    for r in share_rules:
        dc_ids = r['dc_ids'].split(';')
        share_data[(r['customer_id'], r['product_id'])] = {
            'dcs': dc_ids,
            'share': float(r['min_horizon_share'])
        }

    # Split rules
    split_data = {}
    for r in split_rules:
        split_data[(r['month'], r['customer_id'], r['product_id'], r['dc_id'])] = float(r['min_fraction_of_demand'])

    # Transport modes
    mode_data = {}
    for r in transport_modes:
        key = (r['route_type'], r['from_id'], r['to_id'], r['mode_id'])
        mode_data[key] = {
            'cap': float(r['monthly_capacity_tons']),
            'min': float(r['min_mode_tons_if_used']),
            'cost_mult': float(r['cost_multiplier']),
            'co2_mult': float(r['co2_multiplier'])
        }

    # Monthly mode capacity
    mm_cap = {}
    for r in mode_cap:
        mm_cap[(r['month'], r['mode_id'])] = float(r['max_tons'])

    # Demand
    demand_data = {}
    for r in demand:
        demand_data[(r['month'], r['customer_id'], r['product_id'])] = float(r['demand_tons'])

    # Create SCIP model
    model = Model('supply_planning')
    model.setParam('gaprel', 0.0005)

    # Time limit
    time_limit = 300  # default 5 minutes
    if 'ORCLAW_SOLVE_TIME_LIMIT_SECONDS' in os.environ:
        time_limit = min(time_limit, float(os.environ['ORCLAW_SOLVE_TIME_LIMIT_SECONDS']))
    model.setParam('limits/time', time_limit)

    # Variables
    # open[p, m]
    open_var = {}
    for p in plant_list:
        for m in month_list:
            open_var[(p, m)] = model.addVar(vtype='B', name=f'open_{p}_{m}')

    # start[p, m]
    start_var = {}
    for p in plant_list:
        for m in month_list:
            start_var[(p, m)] = model.addVar(vtype='B', name=f'start_{p}_{m}')

    # setup[p, pd, m]
    setup_var = {}
    for p in plant_list:
        for pd in prod_list:
            for m in month_list:
                setup_var[(p, pd, m)] = model.addVar(vtype='B', name=f'setup_{p}_{pd}_{m}')

    # prod_r[p, pd, m]
    prod_r = {}
    for p in plant_list:
        for pd in prod_list:
            for m in month_list:
                prod_r[(p, pd, m)] = model.addVar(lb=0, name=f'prod_r_{p}_{pd}_{m}')

    # prod_o[p, pd, m]
    prod_o = {}
    for p in plant_list:
        for pd in prod_list:
            for m in month_list:
                prod_o[(p, pd, m)] = model.addVar(lb=0, name=f'prod_o_{p}_{pd}_{m}')

    # buy[p, mat, m]
    buy_var = {}
    for p in plant_list:
        for mat in mat_list:
            for m in month_list:
                buy_var[(p, mat, m)] = model.addVar(lb=0, name=f'buy_{p}_{mat}_{m}')

    # lane1[p, dc, m]
    lane1_var = {}
    for p in plant_list:
        for dc in dc_list:
            if (p, dc) in p2d_data:
                for m in month_list:
                    lane1_var[(p, dc, m)] = model.addVar(vtype='B', name=f'lane1_{p}_{dc}_{m}')

    # lane2[dc, c, m]
    lane2_var = {}
    for dc in dc_list:
        for c in cust_list:
            if (dc, c) in d2c_data:
                for m in month_list:
                    lane2_var[(dc, c, m)] = model.addVar(vtype='B', name=f'lane2_{dc}_{c}_{m}')

    # ship1[p, dc, pd, m, mode]
    ship1_var = {}
    for p in plant_list:
        for dc in dc_list:
            if (p, dc) in p2d_data:
                for pd in prod_list:
                    if (p, dc, pd) in excl1:
                        continue
                    for m in month_list:
                        for mode in ['RAIL']:
                            key = ('plant_dc', p, dc, mode)
                            if key in mode_data:
                                ship1_var[(p, dc, pd, m, mode)] = model.addVar(lb=0, name=f'ship1_{p}_{dc}_{pd}_{m}_{mode}')

    # ship2[dc, c, pd, m, mode]
    ship2_var = {}
    for dc in dc_list:
        for c in cust_list:
            if (dc, c) in d2c_data:
                for pd in prod_list:
                    if (dc, c, pd) in excl2:
                        continue
                    for m in month_list:
                        for mode in ['TRUCK']:
                            key = ('dc_customer', dc, c, mode)
                            if key in mode_data:
                                ship2_var[(dc, c, pd, m, mode)] = model.addVar(lb=0, name=f'ship2_{dc}_{c}_{pd}_{m}_{mode}')

    # inv[dc, pd, m]
    inv_var = {}
    for dc in dc_list:
        for pd in prod_list:
            for m in month_list:
                inv_var[(dc, pd, m)] = model.addVar(lb=0, name=f'inv_{dc}_{pd}_{m}')

    # short[c, pd, m]
    short_var = {}
    for c in cust_list:
        for pd in prod_list:
            for m in month_list:
                short_var[(c, pd, m)] = model.addVar(lb=0, name=f'short_{c}_{pd}_{m}')

    # Objective
    obj_terms = []

    # Conversion + overtime
    for p in plant_list:
        for pd in prod_list:
            if (p, pd) in pp_cost:
                for m in month_list:
                    obj_terms.append(pp_cost[(p, pd)]['reg_cost'] * prod_r[(p, pd, m)])
                    obj_terms.append(pp_cost[(p, pd)]['ot_cost'] * prod_o[(p, pd, m)])

    # Setup
    for p in plant_list:
        for pd in prod_list:
            if (p, pd) in pp_rule:
                for m in month_list:
                    obj_terms.append(pp_rule[(p, pd)]['setup_cost'] * setup_var[(p, pd, m)])

    # Material
    for p in plant_list:
        for mat in mat_list:
            for m in month_list:
                if (m, p, mat) in mat_sup:
                    obj_terms.append(mat_sup[(m, p, mat)]['cost'] * buy_var[(p, mat, m)])

    # Fixed + startup
    for p in plant_list:
        for m in month_list:
            obj_terms.append(plant_data[p]['fixed_cost'] * open_var[(p, m)])
            obj_terms.append(plant_data[p]['startup_cost'] * start_var[(p, m)])

    # Lane fixed
    for p in plant_list:
        for dc in dc_list:
            if (p, dc) in p2d_data:
                for m in month_list:
                    obj_terms.append(p2d_data[(p, dc)]['fixed'] * lane1_var[(p, dc, m)])
    for dc in dc_list:
        for c in cust_list:
            if (dc, c) in d2c_data:
                for m in month_list:
                    obj_terms.append(d2c_data[(dc, c)]['fixed'] * lane2_var[(dc, c, m)])

    # Transport
    for (p, dc, pd, m, mode), var in ship1_var.items():
        key = ('plant_dc', p, dc, mode)
        if key in mode_data:
            obj_terms.append(p2d_data[(p, dc)]['cost'] * mode_data[key]['cost_mult'] * var)
    for (dc, c, pd, m, mode), var in ship2_var.items():
        key = ('dc_customer', dc, c, mode)
        if key in mode_data:
            obj_terms.append(d2c_data[(dc, c)]['cost'] * mode_data[key]['cost_mult'] * var)

    # Holding
    for dc in dc_list:
        for pd in prod_list:
            for m in month_list:
                obj_terms.append(dc_data[dc]['holding'] * prod_mult[pd]['hold'] * inv_var[(dc, pd, m)])

    # Shortage
    for c in cust_list:
        for pd in prod_list:
            for m in month_list:
                obj_terms.append(cust_data[c] * prod_mult[pd]['short'] * short_var[(c, pd, m)])

    model.setObjective(quicksum(obj_terms), sense='min')

    # Constraints

    # 1. Startup logic
    for p in plant_list:
        for i, m in enumerate(month_list):
            if i == 0:
                model.addCons(start_var[(p, m)] >= open_var[(p, m)] - plant_data[p]['initial_open'], name=f'startup_{p}_{m}')
            else:
                prev_m = month_list[i-1]
                model.addCons(start_var[(p, m)] >= open_var[(p, m)] - open_var[(p, prev_m)], name=f'startup_{p}_{m}')
            model.addCons(open_var[(p, m)] >= start_var[(p, m)], name=f'open_ge_start_{p}_{m}')

    # 2. Min uptime
    for p in plant_list:
        mu = plant_data[p]['min_uptime']
        for i, m in enumerate(month_list):
            for j in range(1, mu):
                if i + j < len(month_list):
                    m2 = month_list[i+j]
                    model.addCons(open_var[(p, m2)] >= start_var[(p, m)], name=f'uptime_{p}_{m}_{m2}')

    # 3. Production capacity
    for p in plant_list:
        for pd in prod_list:
            if (p, pd) in pp_cost:
                for m in month_list:
                    if (m, p) in avail_data:
                        reg_cap = plant_data[p]['reg_cap'] * avail_data[(m, p)]['reg']
                        ot_cap = plant_data[p]['ot_cap'] * avail_data[(m, p)]['ot']
                        model.addCons(prod_r[(p, pd, m)] <= pp_cost[(p, pd)]['reg_cons'] * reg_cap * open_var[(p, m)], name=f'cap_r_{p}_{pd}_{m}')
                        model.addCons(prod_o[(p, pd, m)] <= pp_cost[(p, pd)]['ot_cons'] * ot_cap * open_var[(p, m)], name=f'cap_o_{p}_{pd}_{m}')

    # 4. Setup logic
    for p in plant_list:
        for pd in prod_list:
            if (p, pd) in pp_rule:
                rule = pp_rule[(p, pd)]
                for m in month_list:
                    # Qualified
                    if month_idx[m] < month_idx.get(rule['qual_month'], 0):
                        model.addCons(setup_var[(p, pd, m)] == 0, name=f'qual_{p}_{pd}_{m}')
                    # Setup implies open
                    model.addCons(setup_var[(p, pd, m)] <= open_var[(p, m)], name=f'setup_open_{p}_{pd}_{m}')
                    # Max output
                    model.addCons(prod_r[(p, pd, m)] + prod_o[(p, pd, m)] <= rule['max_out'] * setup_var[(p, pd, m)], name=f'max_out_{p}_{pd}_{m}')
                    # Min batch
                    if rule['min_batch'] > 0:
                        model.addCons(prod_r[(p, pd, m)] + prod_o[(p, pd, m)] >= rule['min_batch'] * setup_var[(p, pd, m)], name=f'min_batch_{p}_{pd}_{m}')

    # 5. Plant min run
    for p in plant_list:
        for m in month_list:
            total_prod = quicksum(prod_r[(p, pd, m)] + prod_o[(p, pd, m)] for pd in prod_list if (p, pd) in pp_cost)
            model.addCons(total_prod >= plant_data[p]['min_run'] * open_var[(p, m)], name=f'min_run_{p}_{m}')

    # 6. Material balance
    for p in plant_list:
        for mat in mat_list:
            for m in month_list:
                # BOM usage
                bom_usage = quicksum(
                    bom_data.get((pd, mat), 0) * (prod_r[(p, pd, m)] + prod_o[(p, pd, m)])
                    for pd in prod_list if (p, pd) in pp_cost
                )
                model.addCons(bom_usage <= buy_var[(p, mat, m)], name=f'bom_{p}_{mat}_{m}')
                # Max purchase
                if (m, p, mat) in mat_sup:
                    model.addCons(buy_var[(p, mat, m)] <= mat_sup[(m, p, mat)]['max'], name=f'max_buy_{p}_{mat}_{m}')
                # Contract minimum
                if (m, p, mat) in mat_con:
                    model.addCons(buy_var[(p, mat, m)] >= mat_con[(m, p, mat)] * open_var[(p, m)], name=f'contract_{p}_{mat}_{m}')

    # 7. Lane constraints (plant to DC)
    for p in plant_list:
        for dc in dc_list:
            if (p, dc) in p2d_data:
                for m in month_list:
                    # Lane capacity
                    total_ship = quicksum(ship1_var.get((p, dc, pd, m, mode), 0) for pd in prod_list for mode in ['RAIL'])
                    model.addCons(total_ship <= p2d_data[(p, dc)]['cap'] * lane1_var[(p, dc, m)], name=f'lane1_cap_{p}_{dc}_{m}')
                    # Lane minimum
                    model.addCons(total_ship >= p2d_data[(p, dc)]['min'] * lane1_var[(p, dc, m)], name=f'lane1_min_{p}_{dc}_{m}')

    # 8. Lane constraints (DC to customer)
    for dc in dc_list:
        for c in cust_list:
            if (dc, c) in d2c_data:
                for m in month_list:
                    total_ship = quicksum(ship2_var.get((dc, c, pd, m, mode), 0) for pd in prod_list for mode in ['TRUCK'])
                    model.addCons(total_ship <= d2c_data[(dc, c)]['cap'] * lane2_var[(dc, c, m)], name=f'lane2_cap_{dc}_{c}_{m}')
                    model.addCons(total_ship >= d2c_data[(dc, c)]['min'] * lane2_var[(dc, c, m)], name=f'lane2_min_{dc}_{c}_{m}')

    # 9. DC inventory balance
    for dc in dc_list:
        for pd in prod_list:
            for i, m in enumerate(month_list):
                inbound = quicksum(ship1_var.get((p, dc, pd, m, mode), 0) for p in plant_list for mode in ['RAIL'])
                outbound = quicksum(ship2_var.get((dc, c, pd, m, mode), 0) for c in cust_list for mode in ['TRUCK'])
                if i == 0:
                    model.addCons(inv_var[(dc, pd, m)] == inbound - outbound, name=f'inv_{dc}_{pd}_{m}')
                else:
                    prev_m = month_list[i-1]
                    model.addCons(inv_var[(dc, pd, m)] == inv_var[(dc, pd, prev_m)] + inbound - outbound, name=f'inv_{dc}_{pd}_{m}')

    # 10. DC storage capacity
    for dc in dc_list:
        for m in month_list:
            model.addCons(quicksum(inv_var[(dc, pd, m)] for pd in prod_list) <= dc_data[dc]['storage'], name=f'storage_{dc}_{m}')

    # 11. Product inventory caps
    for (m, dc, pd), cap in inv_cap_data.items():
        model.addCons(inv_var[(dc, pd, m)] <= cap, name=f'inv_cap_{dc}_{pd}_{m}')

    # 12. Safety stock
    for (m, dc, pd), ss in safety_data.items():
        model.addCons(inv_var[(dc, pd, m)] >= ss, name=f'safety_{dc}_{pd}_{m}')

    # 13. DC throughput
    for dc in dc_list:
        for m in month_list:
            inbound = quicksum(ship1_var.get((p, dc, pd, m, mode), 0) for p in plant_list for pd in prod_list for mode in ['RAIL'])
            model.addCons(inbound <= dc_data[dc]['inbound'], name=f'inbound_{dc}_{m}')
            outbound = quicksum(ship2_var.get((dc, c, pd, m, mode), 0) for c in cust_list for pd in prod_list for mode in ['TRUCK'])
            model.addCons(outbound <= dc_data[dc]['outbound'], name=f'outbound_{dc}_{m}')

    # 14. Demand balance
    for c in cust_list:
        for pd in prod_list:
            for m in month_list:
                delivered = quicksum(ship2_var.get((dc, c, pd, m, mode), 0) for dc in dc_list for mode in ['TRUCK'])
                d = demand_data.get((m, c, pd), 0)
                model.addCons(delivered + short_var[(c, pd, m)] == d, name=f'demand_{c}_{pd}_{m}')

    # 15. Service level
    for c in cust_list:
        for pd in prod_list:
            if (c, pd) in service_data:
                sr = service_data[(c, pd)]
                # Monthly shortage fraction
                for m in month_list:
                    d = demand_data.get((m, c, pd), 0)
                    if d > 0:
                        model.addCons(short_var[(c, pd, m)] <= sr['max_short'] * d, name=f'monthly_short_{c}_{pd}_{m}')
                # Horizon fill rate
                total_demand = quicksum(demand_data.get((m, c, pd), 0) for m in month_list)
                total_short = quicksum(short_var[(c, pd, m)] for m in month_list)
                model.addCons(total_short <= (1 - sr['fill']) * total_demand, name=f'fill_rate_{c}_{pd}')

    # 16. CO2 budget
    for m in month_list:
        co2_terms = []
        # Material
        for p in plant_list:
            for mat in mat_list:
                if (m, p, mat) in mat_sup:
                    co2_terms.append(mat_sup[(m, p, mat)]['co2'] * buy_var[(p, mat, m)])
        # Production
        for p in plant_list:
            for pd in prod_list:
                if (p, pd) in pp_cost:
                    co2_terms.append(pp_cost[(p, pd)]['co2'] * (prod_r[(p, pd, m)] + prod_o[(p, pd, m)]))
        # Transport
        for (p, dc, pd, mode), var in [(k, v) for k, v in ship1_var.items() if k[3] == m]:
            key = ('plant_dc', p, dc, mode)
            if key in mode_data:
                co2_terms.append(p2d_data[(p, dc)]['co2'] * mode_data[key]['co2_mult'] * var)
        for (dc, c, pd, mode), var in [(k, v) for k, v in ship2_var.items() if k[3] == m]:
            key = ('dc_customer', dc, c, mode)
            if key in mode_data:
                co2_terms.append(d2c_data[(dc, c)]['co2'] * mode_data[key]['co2_mult'] * var)
        model.addCons(quicksum(co2_terms) <= co2_bud[m], name=f'co2_{m}')

    # 17. Share rules
    for (c, pd), rule in share_data.items():
        approved_dcs = rule['dcs']
        share = rule['share']
        # Total delivered
        total_delivered = quicksum(ship2_var.get((dc, c, pd, m, mode), 0) for dc in dc_list for m in month_list for mode in ['TRUCK'])
        # Delivered from approved DCs
        approved_delivered = quicksum(ship2_var.get((dc, c, pd, m, mode), 0) for dc in approved_dcs for m in month_list for mode in ['TRUCK'])
        model.addCons(approved_delivered >= share * total_delivered, name=f'share_{c}_{pd}')

    # 18. Split delivery rules
    for (m, c, pd, dc), frac in split_data.items():
        d = demand_data.get((m, c, pd), 0)
        delivered_from_dc = quicksum(ship2_var.get((dc, c, pd, m, mode), 0) for mode in ['TRUCK'])
        model.addCons(delivered_from_dc >= frac * d, name=f'split_{c}_{pd}_{dc}_{m}')

    # Solve
    model.optimize()

    # Get solution
    status = model.getStatus()
    obj_val = model.getObjVal()

    print(f"Status: {status}")
    print(f"Objective: {obj_val:.2f}")

    # Write solution
    with open(f'{out_dir}/solution.csv', 'w', newline='') as f:
        writer = csv.writer(f)
        writer.writerow(['variable', 'month', 'item', 'from', 'to', 'mode_id', 'quantity_tons'])

        # Regular production
        for p in plant_list:
            for pd in prod_list:
                for m in month_list:
                    val = model.getVal(prod_r[(p, pd, m)])
                    if val > 1e-8:
                        writer.writerow(['regular_production', m, pd, p, '', '', f'{val:.8f}'])

        # Overtime production
        for p in plant_list:
            for pd in prod_list:
                for m in month_list:
                    val = model.getVal(prod_o[(p, pd, m)])
                    if val > 1e-8:
                        writer.writerow(['overtime_production', m, pd, p, '', '', f'{val:.8f}'])

        # Ship plant to DC
        for (p, dc, pd, m, mode), var in ship1_var.items():
            val = model.getVal(var)
            if val > 1e-8:
                writer.writerow(['ship_plant_dc', m, pd, p, dc, mode, f'{val:.8f}'])

        # Ship DC to customer
        for (dc, c, pd, m, mode), var in ship2_var.items():
            val = model.getVal(var)
            if val > 1e-8:
                writer.writerow(['ship_dc_customer', m, pd, dc, c, mode, f'{val:.8f}'])

        # Inventory
        for dc in dc_list:
            for pd in prod_list:
                for m in month_list:
                    val = model.getVal(inv_var[(dc, pd, m)])
                    if val > 1e-8:
                        writer.writerow(['inventory', m, pd, '', dc, '', f'{val:.8f}'])

        # Shortage
        for c in cust_list:
            for pd in prod_list:
                for m in month_list:
                    val = model.getVal(short_var[(c, pd, m)])
                    if val > 1e-8:
                        writer.writerow(['shortage', m, pd, '', c, '', f'{val:.8f}'])

        # Product setup
        for p in plant_list:
            for pd in prod_list:
                for m in month_list:
                    val = model.getVal(setup_var[(p, pd, m)])
                    if val > 0.5:
                        writer.writerow(['product_setup', m, pd, p, '', '', '1'])

    print("Solution written to /app/submissions/solution.csv")

if __name__ == '__main__':
    main()
